x0a//\x20\x20\x20\x20\x20\x20Adds\x20a\x20listener\x20on\x20the\x20host\x20element\x20itself.\x0a//\x20\x20\x20\x20\x20\x20→\x20Auto-removed\x20when\x20the\x20control\x20is\x20disconnected\x20from\x20DOM.\x0a//\x20\x20\x20\x20\x20\x20Returns\x20{\x20remove()\x20}\x20for\x20early\x20removal.\x0a//\x0a//\x20\x20el.addEventListener(\x27click\x27,\x20handler)\x20\x20\x20←\x20on\x20a\x20child\x20element\x20(manual\x20cleanup)\x0a\x0a//\x20──\x203.\x20Properties\x20(defined\x20in\x20Properties\x20tab)\x20────────────────────────────────\x0a//\x20\x20instance.myProp\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20read\x20/\x20write\x20a\x20declared\x20property\x0a//\x20\x20instance[\x27myProp\x27]\x20\x20\x20\x20\x20\x20\x20same\x20—\x20useful\x20for\x20dynamic\x20names\x0a\x0a//\x20──\x204.\x20Relative\x20OID\x20path\x20─────────────────────────────────────────────────────\x0a//\x20\x20instance._getRelativeSignalsPath()\x0a//\x20\x20\x20\x20\x20\x20Returns\x20the\x20OID\x20prefix\x20set\x20by\x20the\x20parent\x20screen/viewer.\x0a//\x20\x20\x20\x20\x20\x20Relative\x20signals\x20start\x20with\x20\x27.\x27\x20→\x20prepend\x20this\x20prefix\x20yourself,\x20or\x20let\x0a//\x20\x20\x20\x20\x20\x20iobrokerHandler.getNormalizedSignalName()\x20do\x20it.\x0a\x0a//\x20──\x205.\x20ioBroker\x20state\x20(iobrokerHandler)\x20──────────────────────────────────────\x0a//\x20\x20Must\x20import\x20at\x20top:\x20import\x20{\x20iobrokerHandler\x20}\x20from\x20\x27../common/IobrokerHandler.js\x27;\x0a//\x0a//\x20\x20Read\x20a\x20state\x20once:\x0a//\x20\x20\x20\x20const\x20state\x20=\x20await\x20iobrokerHandler.getState(\x27hm-rpc.0.ABC.STATE\x27);\x0a//\x20\x20\x20\x20console.log(state.val,\x20state.ts,\x20state.ack);\x0a//\x0a//\x20\x20Write\x20a\x20state:\x0a//\x20\x20\x20\x20await\x20iobrokerHandler.setState(\x27hm-rpc.0.ABC.STATE\x27,\x20true);\x0a//\x20\x20\x20\x20await\x20iobrokerHandler.setState(\x27hm-rpc.0.ABC.STATE\x27,\x20{\x20val:\x2042,\x20ack:\x20false\x20});\x0a//\x0a//\x20\x20Subscribe\x20to\x20state\x20changes\x20(remember\x20to\x20unsubscribe\x20on\x20disconnect!):\x0a//\x20\x20\x20\x20const\x20handler\x20=\x20(id,\x20state)\x20=>\x20{\x20console.log(id,\x20state.val);\x20};\x0a//\x20\x20\x20\x20await\x20iobrokerHandler.subscribeState(\x27hm-rpc.0.ABC.STATE\x27,\x20handler);\x0a//\x20\x20\x20\x20//\x20in\x20disconnectedCallback:\x0a//\x20\x20\x20\x20iobrokerHandler.unsubscribeState(\x27hm-rpc.0.ABC.STATE\x27,\x20handler);\x0a//\x0a//\x20\x20Get\x20an\x20ioBroker\x20object\x20(type/role/unit/min/max/…):\x0a//\x20\x20\x20\x20const\x20obj\x20=\x20await\x20iobrokerHandler.getObject(\x27hm-rpc.0.ABC.STATE\x27);\x0a//\x0a//\x20\x20Current\x20user\x20and\x20groups:\x0a//\x20\x20\x20\x20const\x20user\x20=\x20await\x20iobrokerHandler.getCurrentUser();\x20//\x20{\x20id,\x20groups\x20}\x0a//\x0a//\x20\x20Historic\x20data\x20(requires\x20History\x20adapter):\x0a//\x20\x20\x20\x20const\x20{\x20values\x20}\x20=\x20await\x20iobrokerHandler.getHistoricData(\x0a//\x20\x20\x20\x20\x20\x20\x20\x20\x27hm-rpc.0.ABC.STATE\x27,\x0a//\x20\x20\x20\x20\x20\x20\x20\x20{\x20start:\x20Date.now()\x20-\x203600000,\x20end:\x20Date.now(),\x20count:\x20100,\x20aggregate:\x20\x27none\x27\x20}\x0a//\x20\x20\x20\x20);\x0a//\x0a//\x20\x20Language:\x0a//\x20\x20\x20\x20console.log(iobrokerHandler.language);\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20//\x20\x27en\x27\x20|\x20\x27de\x27\x20|\x20\x27ru\x27\x20|\x20…\x0a//\x20\x20\x20\x20iobrokerHandler.languageChanged.on(lang\x20=>\x20{});\x20//\x20subscribe\x20to\x20language\x20switch\x0a//\x0a//\x20\x20Low-level\x20socket\x20connection\x20(for\x20advanced\x20use):\x0a//\x20\x20\x20\x20iobrokerHandler.connection.subscribeState(id,\x20handler);\x0a//\x20\x20\x20\x20iobrokerHandler.connection.getStates(pattern);\x20\x20\x20//\x20wildcard\x20query\x0a\x0a//\x20──\x206.\x20Navigation\x20&\x20Dialogs\x20\x20(window.RUNTIME)\x20────────────────────────────────\x0a//\x20\x20Open\x20a\x20screen\x20(replaces\x20current\x20view):\x0a//\x20\x20\x20